#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# Registers Settle with Google, so its login and invite pages offer "Sign in with Google", for the
# hosted instance and its staging copy: one Google Cloud project, its consent screen, and one Web
# client with both servers' redirect URIs. Then it puts the client on the VPS, staging first.
#
# Run it from anywhere: bash scripts/google-sign-in-wizard.sh
#
# What you type is saved outside this repo, in ~/.config/settle/google-sign-in.env (only you can
# read it), so a second run picks up where you stopped. No address of yours is written into the
# repo: the wizard asks for them.
#
# The VPS stages need infra's Settle compose file to read /opt/apps/settle-<env>/google.env; the
# wizard checks, and says so if it doesn't yet.

ENV_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/settle/google-sign-in.env"
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE"
chmod 600 "$ENV_FILE"

TOTAL_STAGES=8

banner "Sign in with Google for Settle"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Your two Settle addresses"
say "Google will only send people back to addresses you list, so first: where do"
say "your two Settle servers live? Type just the name, like settle.example.com,"
say "with no https:// and no slash."
ask PROD_HOST "The real one (prod):"
ask STAGING_HOST "The test copy (staging):"
PROD_HOST=${PROD_HOST#https://}; PROD_HOST=${PROD_HOST%/}
STAGING_HOST=${STAGING_HOST#https://}; STAGING_HOST=${STAGING_HOST%/}
write_env PROD_HOST "$PROD_HOST"
write_env STAGING_HOST "$STAGING_HOST"
PROD_REDIRECT="https://$PROD_HOST/auth/google/callback"
STAGING_REDIRECT="https://$STAGING_HOST/auth/google/callback"
# The domain you own: the last two parts of the name. Wrong for names like x.co.uk; the stage that
# uses it says so.
OWN_DOMAIN=$(printf '%s' "$PROD_HOST" | awk -F. '{ print $(NF-1) "." $NF }')
say ""
note "Google will send people back to these two pages after they sign in:"
note "  $PROD_REDIRECT"
note "  $STAGING_REDIRECT"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Make a Google Cloud project"
say "A project is Google's folder for one app. It's free; this needs no billing."
open_url "https://console.cloud.google.com/projectcreate"
step "Sign in with the Google account you want to own this (your own Gmail is fine)."
step "Project name: Settle. Leave Location as \"No organization\"."
step "Click Create, and wait for the bell icon to say it's done (about a minute)."
step "Under the name box, Google showed a Project ID (like settle-123456). Copy it."
note "Lost it? The project picker at the top of the console lists each project's ID."
ask GOOGLE_PROJECT "Paste the Project ID:"
write_env GOOGLE_PROJECT "$GOOGLE_PROJECT"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The consent screen: what people see at Google"
say "This is the \"Settle wants to know who you are\" screen Google shows."
open_url "https://console.cloud.google.com/auth/overview?project=$GOOGLE_PROJECT"
step "Check the project picker at the top says Settle. Click Get started."
step "App name: Settle. User support email: pick your email. Next."
step "Audience: External (anyone with a Google account can try; Settle still lets in"
say "    only people with an invite). Next."
step "Contact information: your email. Next. Tick that you agree. Continue, then Create."
note "If there is no Get started button, this was done already: just continue."
pause "Done? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Your domain, and the three things Settle asks for"
say "Two small settings on the same screens."
open_url "https://console.cloud.google.com/auth/branding?project=$GOOGLE_PROJECT"
step "Scroll to Authorized domains. Click Add domain, type: $OWN_DOMAIN"
note "  That is the part of $PROD_HOST you bought. If your name ends in"
note "  something like .co.uk, type the last three parts instead."
step "Click Save at the bottom."
pause "Saved? Press Enter for the second setting."
open_url "https://console.cloud.google.com/auth/scopes?project=$GOOGLE_PROJECT"
step "Click Add or remove scopes. Tick these three, and nothing else:"
say "    openid"
say "    .../auth/userinfo.email"
say "    .../auth/userinfo.profile"
step "Click Update, then Save."
note "These only say who someone is: their Google id, email and name. With only these,"
note "the app can stay in Testing for good: no review by Google, no list of test users,"
note "and sign-ins don't expire after 7 days. Don't add any other scope."
note "On the Audience page, leave the status as Testing. Don't press Publish app."
pause "Done? Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The Web client: Settle's id and secret"
say "This makes the pair of values Settle uses to talk to Google."
warn "Google shows the secret only once, at the end of this stage. Have this window ready."
open_url "https://console.cloud.google.com/auth/clients?project=$GOOGLE_PROJECT"
step "Click Create client. Application type: Web application. Name: Settle."
step "Leave Authorized JavaScript origins empty."
step "Under Authorized redirect URIs, click Add URI twice and paste one in each:"
say "    $PROD_REDIRECT"
say "    $STAGING_REDIRECT"
step "Click Create. A box shows the Client ID and the Client secret."
step "Also click Download JSON there, and keep that file somewhere safe, as a spare."
ask SETTLE_GOOGLE_CLIENT_ID "Paste the Client ID (ends in .apps.googleusercontent.com):"
while [[ "$SETTLE_GOOGLE_CLIENT_ID" != *.apps.googleusercontent.com ]]; do
  warn "That doesn't end in .apps.googleusercontent.com. Copy the Client ID line again."
  ask SETTLE_GOOGLE_CLIENT_ID "Paste the Client ID:"
done
ask_secret SETTLE_GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden as you type):"
while [[ -z "$SETTLE_GOOGLE_CLIENT_SECRET" ]]; do
  ask_secret SETTLE_GOOGLE_CLIENT_SECRET "Nothing came through. Paste the Client secret:"
done
write_env SETTLE_GOOGLE_CLIENT_ID "$SETTLE_GOOGLE_CLIENT_ID"
write_env SETTLE_GOOGLE_CLIENT_SECRET "$SETTLE_GOOGLE_CLIENT_SECRET"
note "Lost the secret? The client's page can make a new one (Add secret), then delete the old."
note "Google says new settings can take from 5 minutes to a few hours to work."
pause

# put_on_vps ENV: writes google.env for one server and restarts it on the image it runs now.
put_on_vps() {
  local env="$1" dir="/opt/apps/settle-$1" tag
  if ! ssh "$VPS_SSH" "sudo -n true"; then
    warn "Couldn't run sudo on $VPS_SSH over SSH (wrong name, not on Tailscale, or sudo wants a password)."
    SKIPPED+=("Settle $env on the VPS: ssh $VPS_SSH with sudo didn't work")
    return 1
  fi
  if ! ssh "$VPS_SSH" "sudo grep -q google.env $dir/compose.yml"; then
    warn "$dir/compose.yml doesn't read google.env yet, so Settle wouldn't see the client."
    say "infra needs a small change first: see \"For the infra repo\" in the claude-app handoff's"
    say "report from track C. Once it's applied, run this wizard again: Enter keeps every answer."
    SKIPPED+=("Settle $env on the VPS: infra's compose file must read google.env first")
    return 1
  fi
  tag=$(ssh "$VPS_SSH" "sudo sed -n 's/^IMAGE_TAG=//p' $dir/.env")
  if [[ -z "$tag" ]]; then
    warn "Couldn't read which image settle-$env runs, from $dir/.env."
    SKIPPED+=("Settle $env on the VPS: no IMAGE_TAG in $dir/.env")
    return 1
  fi
  say "This writes $dir/google.env (only root can read it) and restarts settle-$env"
  say "on the image it runs now ($tag). It's down for a few seconds."
  if ! confirm "Go ahead with settle-$env?"; then
    SKIPPED+=("Settle $env on the VPS: you said not yet")
    return 1
  fi
  printf 'SETTLE_GOOGLE_CLIENT_ID=%s\nSETTLE_GOOGLE_CLIENT_SECRET=%s\n' \
    "$SETTLE_GOOGLE_CLIENT_ID" "$SETTLE_GOOGLE_CLIENT_SECRET" |
    ssh "$VPS_SSH" "sudo install -m 600 -o root -g root /dev/stdin $dir/google.env"
  printf '  %s✓ wrote%s %s/google.env\n' "$GREEN" "$RESET" "$dir"
  ssh "$VPS_SSH" "sudo deploy-app settle $env $tag"
}

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Put it on staging"
say "Now Settle needs the id and secret. Staging first, so prod is untouched until"
say "you've tried it."
say "How do you reach the VPS over SSH? The name you'd type after ssh, such as the"
say "Tailscale name of the box."
ask VPS_SSH "SSH name of the VPS:"
write_env VPS_SSH "$VPS_SSH"
STAGING_DONE=no
if put_on_vps staging; then STAGING_DONE=yes; fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Try it on staging"
if [[ "$STAGING_DONE" == yes ]]; then
  open_url "https://$STAGING_HOST/login"
  step "Log out first if you're logged in (Account page). The login page should now"
  say "    show Log in with Google at the top."
  step "Click it, pick the Google account whose email is the one you log in to Settle with."
  step "You should land in Settle, logged in. From now on that Google account works for you."
  note "\"no account here\": your Google email differs from your Settle one. Change your"
  note "Settle email on the Account page to match, or ask for an invite to that address."
  note "\"redirect_uri_mismatch\" from Google: the redirect URI in stage 5 has a typo, or"
  note "Google hasn't caught up yet; wait a few minutes."
  if ! confirm "Did Log in with Google work on staging?"; then
    SKIPPED+=("Google sign-in on staging didn't work yet, so prod was left alone")
    finish
    exit 1
  fi
else
  warn "Staging wasn't set up in the last stage, so there's nothing to try yet."
  pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Put it on prod"
if [[ "$STAGING_DONE" == yes ]]; then
  if put_on_vps prod; then
    open_url "https://$PROD_HOST/login"
    step "Check the login page shows Log in with Google. Tell the people you invite they"
    say "    can choose Join with Google on their invite link."
  fi
else
  warn "Skipped: prod waits until Google sign-in has worked on staging."
  SKIPPED+=("Settle prod on the VPS: after staging works")
fi
pause

finish
note "Your answers are saved in $ENV_FILE. Run the wizard again to change any of them."
